import{_ as e,o as i,c as a,a2 as t}from"./chunks/framework.mRCPFc5l.js";const k=JSON.parse('{"title":"配置（gflags）","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/configuration.md","filePath":"zh/guide/configuration.md","lastUpdated":1790847150000}'),d={name:"zh/guide/configuration.md"};function l(n,s,o,h,r,p){return i(),a("div",null,[...s[0]||(s[0]=[t('<h1 id="配置-gflags" tabindex="-1">配置（gflags） <a class="header-anchor" href="#配置-gflags" aria-label="Permalink to &quot;配置（gflags）&quot;">​</a></h1><p>NeoFlux 使用 <a href="https://github.com/gflags/gflags" target="_blank" rel="noreferrer">gflags</a> 做运行时配置，用 <a href="https://github.com/google/glog" target="_blank" rel="noreferrer">glog</a> 记录日志。下列参数均为可选，在命令行传入：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\build\\bin\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">hello_neoflux.exe</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">render_backend</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">gl </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">target_fps</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">120</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">logtostderr</span></span></code></pre></div><h2 id="完整参数表" tabindex="-1">完整参数表 <a class="header-anchor" href="#完整参数表" aria-label="Permalink to &quot;完整参数表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>默认值</th><th>含义</th></tr></thead><tbody><tr><td><code>--render_backend</code></td><td><code>string</code></td><td><code>&quot;vulkan&quot;</code></td><td>选择 tgfx 渲染后端，可选 <code>vulkan</code>、<code>gl</code>、<code>cpu</code>。</td></tr><tr><td><code>--target_fps</code></td><td><code>int32</code></td><td><code>60</code></td><td>应用事件循环的目标帧率。</td></tr><tr><td><code>--render_queue_capacity</code></td><td><code>uint64</code></td><td><code>2048</code></td><td>SPSC 渲染命令环形队列容量，向上取整为 2 的幂；保留一个槽位，可用命令数 = <code>capacity - 1</code>。</td></tr><tr><td><code>--verbose_logging</code></td><td><code>bool</code></td><td><code>false</code></td><td>开启 <code>VLOG(1)</code> 并把 INFO 日志镜像到 stderr。</td></tr><tr><td><code>--logtostderr</code></td><td><code>bool</code></td><td><code>false</code></td><td>开启后所有日志写到 stderr 而非文件。</td></tr><tr><td><code>--log_dir</code></td><td><code>string</code></td><td><code>&quot;./logs&quot;</code></td><td><code>.log</code> 文件目录（自动创建），仅在未开启 <code>--logtostderr</code> 时生效。</td></tr></tbody></table><h3 id="render-backend" tabindex="-1"><code>--render_backend</code> <a class="header-anchor" href="#render-backend" aria-label="Permalink to &quot;`--render_backend`&quot;">​</a></h3><p>定义于 <code>src/render/render_layer.cpp</code>，接受三个值：</p><table tabindex="0"><thead><tr><th>取值</th><th>行为</th></tr></thead><tbody><tr><td><code>vulkan</code>（默认）</td><td>预留。尚未实现 —— 打警告并回退到 OpenGL。</td></tr><tr><td><code>gl</code></td><td>OpenGL 后端（当前可用的桌面路径，经 GLFW/WGL）。</td></tr><tr><td><code>cpu</code></td><td>软件光栅化。尚未实现 —— 打警告并回退到 OpenGL。</td></tr></tbody></table><p>无法识别的值也会打警告并走 OpenGL。</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>虽然默认字符串是 <code>&quot;vulkan&quot;</code>，但当前桌面构建的所有选项最终都经由 GL 渲染。 可显式传 <code>--render_backend=gl</code> 表明意图。</p></div><h3 id="target-fps" tabindex="-1"><code>--target_fps</code> <a class="header-anchor" href="#target-fps" aria-label="Permalink to &quot;`--target_fps`&quot;">​</a></h3><p>设置 <code>EventLoop::SetTargetFps()</code>。循环在帧之间睡眠以满足帧率上限；输入事件与 <code>MarkFrameDirty()</code> 会提前唤醒。默认 <code>60</code>。</p><h3 id="render-queue-capacity" tabindex="-1"><code>--render_queue_capacity</code> <a class="header-anchor" href="#render-queue-capacity" aria-label="Permalink to &quot;`--render_queue_capacity`&quot;">​</a></h3><p>配置 <code>RenderLayer</code> 构造的 <code>SpscRingQueue&lt;RenderCommand&gt;</code>。内部向上取整为 2 的幂。 因保留一个槽位区分满/空，请求 <code>2048</code> 实际最多存 <code>2047</code> 条在途命令。若生产者追上 消费者，本帧多余命令被丢弃（限频警告）。</p><div class="warning custom-block"><p class="custom-block-title">仅在出现“render command queue full”警告时再调大</p><p>队列越大越占内存、增加呈现延迟。默认 <code>2048</code> 对一般 widget 树已足够。</p></div><h3 id="verbose-logging" tabindex="-1"><code>--verbose_logging</code> <a class="header-anchor" href="#verbose-logging" aria-label="Permalink to &quot;`--verbose_logging`&quot;">​</a></h3><p>一个便捷开关。开启后 NeoFlux 打开 <code>VLOG(1)</code>（<code>FLAGS_v = 1</code>）并把 INFO 级日志镜像到 stderr。逐帧布局转储（<code>VLOG(1) &lt;&lt; widgetname [x y w h]</code>）就靠它显示。</p><h3 id="logtostderr" tabindex="-1"><code>--logtostderr</code> <a class="header-anchor" href="#logtostderr" aria-label="Permalink to &quot;`--logtostderr`&quot;">​</a></h3><p>这是 glog 内建参数。当 glog 未与 gflags 集成构建时，NeoFlux 会在 gflags 解析之前 预扫描 <code>argv</code>，识别 <code>--logtostderr</code> / <code>--nologtostderr</code>（及 <code>-</code> 短横线形式）。默认关闭， 日志写入文件。</p><h3 id="log-dir" tabindex="-1"><code>--log_dir</code> <a class="header-anchor" href="#log-dir" aria-label="Permalink to &quot;`--log_dir`&quot;">​</a></h3><p>同样是 glog 内建参数，由同一套 argv 预扫描处理。同时接受 <code>--log_dir=路径</code> 与 <code>--log_dir 路径</code> 两种写法。写文件时默认 <code>./logs</code>，自动建目录，并追加 <code>.log</code> 扩展名； 目录无法创建时静默回退到 stderr。</p><h2 id="代码里打日志" tabindex="-1">代码里打日志 <a class="header-anchor" href="#代码里打日志" aria-label="Permalink to &quot;代码里打日志&quot;">​</a></h2><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#include</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &lt;glog/logging.h&gt;</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">LOG</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(INFO) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Application started&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">LOG</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(WARNING) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Font not found, using default&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">LOG</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ERROR) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Rendering failed&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">VLOG</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Detailed per-frame debug info&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // 配 --verbose_logging 显示</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">推荐的开发命令</p><p>示例是 GUI 子系统二进制、没有控制台，运行时建议：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\build\\bin\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">hello_neoflux.exe</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">logtostderr </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">verbose_logging</span></span></code></pre></div></div><h2 id="完整示例" tabindex="-1">完整示例 <a class="header-anchor" href="#完整示例" aria-label="Permalink to &quot;完整示例&quot;">​</a></h2><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\build\\bin\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">hello_neoflux.exe</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> `</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">target_fps</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">144</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> `</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">render_backend</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">gl </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">`</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">render_queue_capacity</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4096</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> `</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">logtostderr </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">`</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">verbose_logging</span></span></code></pre></div><p>即目标 144 FPS、强制 GL 后端、队列扩到 4096，并把详细日志输出到终端。</p>',27)])])}const g=e(d,[["render",l]]);export{k as __pageData,g as default};
